import numpy as np
from scipy.optimize import minimize_scalar

def f_pos(z):
    x = np.sqrt((1 - z**2) / 2)
    return 9 * x**2 * z - 2 * (2 * x + z)

def f_neg(z):
    x = -np.sqrt((1 - z**2) / 2)
    return 9 * x**2 * z - 2 * (2 * x + z)

res_pos = minimize_scalar(f_pos, bounds=(-1, 1), method='bounded')
res_neg = minimize_scalar(f_neg, bounds=(-1, 1), method='bounded')

print("Pos: min_val =", res_pos.fun, "z =", res_pos.x)
print("Neg: min_val =", res_neg.fun, "z =", res_neg.x)

import numpy as np
from scipy.optimize import minimize

def objective(v):
    x, y, z = v
    return 9 * x * y * z - 2 * (x + y + z)

def constraint(v):
    return v[0]**2 + v[1]**2 + v[2]**2 - 1

cons = {'type': 'eq', 'fun': constraint}

# Random sampling to find better starting points
min_val = float('inf')
for _ in range(1000):
    v = np.random.randn(3)
    v /= np.linalg.norm(v)
    res = minimize(objective, v, constraints=cons)
    if res.success:
        min_val = min(min_val, res.fun)

print("Random search minimum:", min_val)
print("-10/3:", -10/3)
